SELECTED_RELATIONS = {"occupation", "educated at", "position held", "country of citizenship",
                      "member of political party", "date of birth", "place of birth", "spouse", "residence"}

# How a text that should be followed by a fact ends, per relation. Matched against the end of the
# text's words (lowercase letters and digits, plus "("). The scripted router retrieves when one
# matches; the report on your models compares them with what your retriever returned.
RELATION_CUES = {
    # "on\d*": a retrieved date with no leading space gives "born on3 June 1888 in", still the same cue.
    "place of birth": [r"\bborn in$", r"\bborn on\d*( \S+)+ in$"],
    "date of birth": [r"\bborn on$", r"\($"],
    "spouse": [r"\bmarried to$", r"\bmarried$"],
    "educated at": [r"\bstudied at$", r"\beducated at$", r"\bgraduated from$"],
    "occupation": [r"\bworked as an?$", r"\bworked as$", r"\bwas an?$"],
    "member of political party": [r"\bmember of the$"],
    "position held": [r"\bserved as( the)?$", r"\belected( to)?$"],
    "residence": [r"\blived in$"],
    "country of citizenship": [r"\bcitizen of$"],
}

# Made-up people, so no real fact can be hardcoded. Keys are in a different order for each.
PERSON_TO_KV = {
    "zara quill": [("date of birth", "12 March 1901"), ("place of birth", "Lowmoor"),
                   ("spouse", "Edwin Quill"), ("occupation", "lighthouse keeper"),
                   ("educated at", "Saltmere College"), ("member of political party", "Harbor Party")],
    "tomas vey": [("occupation", "glassblower"), ("date of birth", "3 June 1888"),
                  ("spouse", "Ilse Varga"), ("place of birth", "Brackwater"),
                  ("residence", "Fenwick"), ("position held", "Mayor of Fenwick")],
}
