# Test 4.x prompt bank, and the facts a correct pipeline retrieves after each prompt with the
# scripted models. "born on" gives two facts in one sentence: the date, then GPT-2 says " in"
# and the place of birth follows. "liked" has no cue, so GPT-2 alone finishes it (" the sea.").
PROMPT_BANK = ["{name} was born on", "{name} was married to", "{name} worked as a", "{name} liked"]
EXPECTED_RELATIONS = [["date of birth", "place of birth"], ["spouse"], ["occupation"], []]
# The scripted GPT-2's next token after each token. Anything else is followed by ".".
BIO_SCRIPT = {" liked": " the", " the": " sea", " sea": "."}
