def preview(items):
    items = [str(x) for x in items]
    more = len(items) - MAX_LISTED
    return "\n".join(items[:MAX_LISTED] + ([f"... ({more} more)"] if more > 0 else []))


class TimeLimitExceeded(Exception):
    pass


def call_with_time_limit(fn, *args, **kwargs):
    """Windows has no SIGALRM, so there is no limit there."""
    if not hasattr(signal, "SIGALRM"):
        return fn(*args, **kwargs)

    def on_timeout(signum, frame):
        raise TimeLimitExceeded()

    previous = signal.signal(signal.SIGALRM, on_timeout)
    signal.alarm(TIME_LIMIT_SECONDS)
    try:
        return fn(*args, **kwargs)
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, previous)


def call_student(fn, name, *args, **kwargs):
    """Calls the student's function. Returns (result, error_message)."""
    if not callable(fn):
        return None, f"{name} is not defined. Don't rename or delete it."
    try:
        return call_with_time_limit(fn, *args, **kwargs), None
    except TimeLimitExceeded:
        return None, f"{name} took longer than {TIME_LIMIT_SECONDS}s on the test data."
    except Exception as e:
        return None, f"{name} raised {type(e).__name__}: {e}"


def function_tree(fn):
    """fn's parsed source, or None if it cannot be read."""
    try:
        return ast.parse(textwrap.dedent(inspect.getsource(fn)))
    except (OSError, TypeError, SyntaxError):
        return None


def loader_calls(fn):
    """The calls inside fn that load a model or tokenizer, e.g. ['AutoTokenizer.from_pretrained']."""
    tree = function_tree(fn)
    if tree is None:
        return []
    calls = {ast.unparse(n.func) for n in ast.walk(tree) if isinstance(n, ast.Call)}
    return sorted(c for c in calls if c.endswith(LOADERS))


def notebook_functions(fn):
    """fn and every notebook function it calls, following calls into those functions."""
    seen, todo = {}, [fn]
    while todo:
        f = todo.pop()
        if not isinstance(f, types.FunctionType) or f.__name__ in seen:
            continue
        seen[f.__name__] = f
        tree = function_tree(f)
        for n in ast.walk(tree) if tree else []:
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name):
                callee = f.__globals__.get(n.func.id)
                if isinstance(callee, types.FunctionType) and callee.__globals__ is f.__globals__:
                    todo.append(callee)
    return seen


def reachable_calls(fn):
    """Every function name called from fn, following calls into the notebook's other functions."""
    called = set()
    for f in notebook_functions(fn).values():
        tree = function_tree(f)
        called |= {n.func.id for n in ast.walk(tree) if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)} \
            if tree else set()
    return called


def missing_on_gradescope(functions):
    """{function name: notebook variables it uses that Gradescope will not have}. Gradescope keeps
    only imports, functions, classes and plain constants such as MAX_TOKENS = 25."""
    found = {}
    for fn in functions:
        for name, f in notebook_functions(fn).items():
            tree = function_tree(f)
            if tree is None:
                continue
            stored = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and not isinstance(n.ctx, ast.Load)}
            stored |= {a.arg for n in ast.walk(tree) if isinstance(n, ast.arguments)
                       for a in n.posonlyargs + n.args + n.kwonlyargs + [n.vararg, n.kwarg] if a}
            loaded = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
            for var in sorted(loaded - stored - SUPPLIED_GLOBALS - set(dir(builtins))):
                value = f.__globals__.get(var)
                if var in f.__globals__ and getattr(value, "__module__", None) != "typing" and \
                        not isinstance(value, (types.ModuleType, type, types.FunctionType, types.BuiltinFunctionType,
                                               int, float, str, bool, type(None))):
                    found.setdefault(name, set()).add(var)
    return found


def normalize(text):
    """Lowercase, punctuation to spaces, repeated spaces collapsed (as fact_match.normalize)."""
    return " ".join(re.sub(r"[^\w\s+#]", " ", str(text).lower()).split())


def contains_value(text, value):
    """Whether value appears in text as whole words, ignoring case, punctuation and spacing."""
    value = normalize(value)
    return bool(value) and re.search(r"(?<!\w)" + re.escape(value) + r"(?!\w)", normalize(text)) is not None


def cue_relation(text):
    """The relation whose RELATION_CUES pattern matches the end of text, or None."""
    words = " ".join(re.findall(r"[a-z0-9]+|\(", str(text).lower()))
    for relation, patterns in RELATION_CUES.items():
        if any(re.search(p, words) for p in patterns):
            return relation
    return None


def ids_of(span):
    """A span's token ids as a flat list."""
    tokens = getattr(span, "tokens", None)
    return tokens.reshape(-1).tolist() if hasattr(tokens, "reshape") else []


def type_name(span):
    """A span's SpanType name, e.g. "RETRIEVED"."""
    return getattr(getattr(span, "span_type", None), "name", "?")

