_cache = {}


def load_nlp():
    if "nlp" not in _cache:
        import spacy
        _cache["nlp"] = spacy.load(SPACY_MODEL)
    return _cache["nlp"]


def tokenize(text):
    """The notebook's tokenize (B.1): spaCy words, lowercased, without accents."""
    return [unidecode.unidecode(t.text.lower()) for t in load_nlp().make_doc(str(text).replace("_", " "))]


class GraderVocab(dict):
    """word -> index. Works like the notebook's Vocab (num_words, word2index, index2word, ...)
    and like the plain dict that read_json gives, so either style of code works."""

    def __init__(self, words=()):
        super().__init__()
        self._index2word = {}
        for word in words:
            self.add_word(word)

    @property
    def _word2index(self):
        return self

    @property
    def _n_words(self):
        return len(self)

    def num_words(self):
        return len(self)

    def word2index(self, word):
        return self.get(word, -1)

    def index2word(self, idx):
        return self._index2word[idx]

    def add_word(self, word):
        if word not in self:
            self._index2word[len(self)] = word
            self[word] = len(self)

    def add_text(self, text):
        for word in tokenize(text):
            self.add_word(word)


def build_vocab():
    """Every word of the test data, in a fixed order."""
    texts = [*PERSON_TO_KV, *TRIGGER_TEXTS, *RETRIEVE_QUERIES, *GENERATE_INPUTS, *GENERATE_WORDS]
    texts += [p.format(name=n) for p in PROMPT_BANK for n in PEOPLE] + list(BIO_SCRIPT.values())
    texts += [AFTER_DATE_OF_BIRTH] + [t for kvs in PERSON_TO_KV.values() for kv in kvs for t in kv]
    return GraderVocab(sorted({w for text in texts for w in tokenize(text)}))


def gpt_tokenizer():
    if "gpt" not in _cache:
        tokenizer = AutoTokenizer.from_pretrained(GPT_TOKENIZER)
        tokenizer.pad_token = tokenizer.eos_token  # as the notebook does
        _cache["gpt"] = tokenizer
    return _cache["gpt"]


def one_token(text):
    ids = gpt_tokenizer().encode(text)
    assert len(ids) == 1, f"{text!r} is {len(ids)} GPT-2 tokens"
    return ids[0]


def scripted_gpt(next_token, device):
    """A tiny real GPT-2 whose logits put PEAK_LOGIT on next_token(t) after each token t, so
    greedy decoding, sampling and model.generate() all pick it. It records every forward call."""
    from transformers import GPT2Config, GPT2LMHeadModel

    class ScriptedGPT(GPT2LMHeadModel):
        def forward(self, *args, **kwargs):
            input_ids = kwargs.get("input_ids", args[0] if args else None)
            past_in = kwargs.get("past_key_values", args[1] if len(args) > 1 else None)
            out = super().forward(*args, **kwargs)
            logits = torch.zeros_like(out.logits)
            if input_ids is not None:
                targets = torch.tensor([[next_token(int(t)) for t in row] for row in input_ids.tolist()],
                                       device=logits.device)
                logits.scatter_(2, targets.unsqueeze(-1), PEAK_LOGIT)
            out.logits = logits
            self.calls.append({"input_ids": None if input_ids is None else input_ids.tolist(),
                               "past_in": past_in, "past_out": out.past_key_values})
            return out

    torch.manual_seed(0)
    config = GPT2Config(vocab_size=len(gpt_tokenizer()), n_positions=4096, n_embd=16, n_layer=1, n_head=2)
    model = ScriptedGPT(config).to(device).eval()
    model.calls = []
    return model


def generate_rule(shift):
    words = [one_token(w) for w in GENERATE_WORDS]
    return lambda t: words[(t + shift) % len(words)]


def bio_rule():
    """The scripted GPT-2 for test 4.x: BIO_SCRIPT, " in" after a date of birth, else "."."""
    tokenizer = gpt_tokenizer()
    table = {one_token(a): one_token(b) for a, b in BIO_SCRIPT.items()}
    for kvs in PERSON_TO_KV.values():
        for relation, value in kvs:
            if relation == "date of birth":
                last_tokens = {tokenizer.encode(value)[-1], tokenizer.encode(" " + value)[-1]}
                table.update({t: one_token(AFTER_DATE_OF_BIRTH) for t in last_tokens})
    period = one_token(".")
    return lambda t: table.get(t, period)


class SpyTokenizer(BertTokenizer):
    """The tiny BERT's tokenizer, recording every call that tokenizes text."""

    def __call__(self, text=None, *args, **kwargs):
        if text is not None:
            self.__dict__.setdefault("text_calls", []).append(str(text)[:200])
        return super().__call__(text, *args, **kwargs)

    def encode(self, text, *args, **kwargs):
        self.__dict__.setdefault("text_calls", []).append(str(text)[:200])
        return super().encode(text, *args, **kwargs)


def spy_tokenizer():
    tokenizer = SpyTokenizer.from_pretrained(ROUTER_TOKENIZER)
    tokenizer.text_calls = []
    return tokenizer


def scripted_router(mode, device):
    """A tiny real BERT classifier that decodes its input and answers by RELATION_CUES.
    mode "cues": retrieve when a cue matches; "inverse": the opposite; "never": never retrieve."""
    from transformers import BertConfig, BertForSequenceClassification
    from transformers.modeling_outputs import SequenceClassifierOutput

    if "router" not in _cache:
        _cache["router"] = BertTokenizer.from_pretrained(ROUTER_TOKENIZER)
    decoder = _cache["router"]

    class ScriptedRouter(BertForSequenceClassification):
        def decide(self, text):
            cue = cue_relation(text) is not None
            return {"cues": cue, "inverse": not cue, "never": False}[mode]

        def forward(self, input_ids=None, *args, **kwargs):
            rows = [] if input_ids is None else input_ids.tolist()
            logits = []
            for row in rows:
                text = decoder.decode(row, skip_special_tokens=True)
                retrieve = self.decide(text)
                self.calls.append({"text": text, "retrieve": retrieve})
                if retrieve:
                    self.last_retrieve_text = text
                logits.append([-ROUTER_LOGIT, ROUTER_LOGIT] if retrieve else [ROUTER_LOGIT, -ROUTER_LOGIT])
            logits = torch.tensor(logits, dtype=torch.float32, device=device).reshape(-1, 2)
            return SequenceClassifierOutput(logits=logits)

    torch.manual_seed(0)
    config = BertConfig(vocab_size=decoder.vocab_size, hidden_size=16, num_hidden_layers=1, num_attention_heads=2,
                        intermediate_size=16, num_labels=2, id2label={0: "NEGATIVE", 1: "POSITIVE"},
                        label2id={"NEGATIVE": 0, "POSITIVE": 1})
    model = ScriptedRouter(config).to(device).eval()
    model.calls, model.last_retrieve_text = [], None
    return model


def scripted_memnet(mode, vocab, device, router=None):
    """Stands in for QKMemNet: forward(x, keys) returns one probability per key (row of keys),
    almost all of it on the key its rule picks. x and keys are multi-hot vectors over vocab.
    mode "sum": key (sum of x's word indices) % number of keys; "reverse": the last key minus that;
    "router": the key named by the cue of the text the router last said to retrieve after."""

    class ScriptedMemNet(torch.nn.Module):
        def __init__(self):
            super().__init__()
            self.unused = torch.nn.Parameter(torch.zeros(1))  # so .to(), .eval() and .parameters() work
            self.calls = []

        def forward(self, x, keys):
            x = torch.as_tensor(x).detach().float().cpu()
            if isinstance(keys, (list, tuple)):
                keys = torch.stack([torch.as_tensor(k).cpu() for k in keys])
            keys = torch.as_tensor(keys).detach().float().cpu()
            size = len(vocab)
            rows = keys.reshape(-1, size) if keys.numel() % size == 0 and keys.numel() else None
            call = {"x_len": x.numel(), "x_active": x.reshape(-1).nonzero().flatten().tolist() if x.numel() == size else [],
                    "n_rows": None if rows is None else rows.shape[0],
                    "rows": [] if rows is None else [r.nonzero().flatten().tolist() for r in rows]}
            n = call["n_rows"] or 1
            if mode == "router":
                target = row_for_relation(call["rows"], cue_relation(router.last_retrieve_text or ""), vocab)
            else:
                target = sum(call["x_active"]) % n
                target = target if mode == "sum" else n - 1 - target
            call["target"] = target
            self.calls.append(call)
            p = torch.softmax(torch.nn.functional.one_hot(torch.tensor(target), n).float() * 20, dim=0).to(device)
            return p.unsqueeze(0) if x.dim() > 1 else p

    return ScriptedMemNet().to(device).eval()


def row_for_relation(rows, relation, vocab):
    """The index of the key row whose words best match relation (0 if none does)."""
    wanted = {vocab.get(w) for w in tokenize(relation)} if relation else set()
    scores = [len(wanted & set(r)) - 0.01 * len(set(r) - wanted) for r in rows]
    return max(range(len(rows)), key=lambda i: scores[i]) if rows and max(scores) > 0 else 0


def row_value(row, kvs, vocab):
    """The value of the kv pair whose key's words best match one key row."""
    words = set(row)
    scores = [len(words & {vocab.get(w) for w in tokenize(k)}) for k, _ in kvs]
    return kvs[max(range(len(kvs)), key=lambda i: scores[i])][1]

