#  Running your functions on the stand-ins
# ------------------------

def span_facts(span, tokenizer):
    """What the tests judge about a returned TokenSpan."""
    if type(span).__name__ != "TokenSpan":
        return {"is_span": False, "type": type(span).__name__}
    tokens = getattr(span, "tokens", None)
    ids = ids_of(span)
    return {"is_span": True, "span_type": type_name(span),
            "shape": list(tokens.shape) if hasattr(tokens, "shape") else None,
            "ids": ids, "text": tokenizer.decode(ids), "given_tokenizer": span.tokenizer is tokenizer}


def trigger_facts(trigger_retrieval, device):
    cases = []
    for mode in ("cues", "inverse"):
        router = scripted_router(mode, device)
        for text in TRIGGER_TEXTS:
            tokenizer = spy_tokenizer()
            calls_before = len(router.calls)
            result, error = call_student(trigger_retrieval, "trigger_retrieval", text, router, tokenizer)
            answer = None
            if not error:
                try:
                    answer = bool(result)
                except Exception as e:
                    error = f"trigger_retrieval should return True or False; got {type(result).__name__} ({e})."
            cases.append({"mode": mode, "text": text, "expected": router.decide(text), "answer": answer,
                          "error": error, "tokenizer_called": bool(tokenizer.text_calls),
                          "router_called": len(router.calls) > calls_before})
    return {"cases": cases}


def generate_case(generate, model, input_ids, tokenizer, **kwargs):
    """Calls generate once. Returns its facts and the cache it returned."""
    calls_before = len(model.calls)
    result, error = call_student(generate, "generate", model, input_ids, tokenizer=tokenizer, **kwargs)
    if error:
        return {"error": error}, None
    if not (isinstance(result, tuple) and len(result) == 2):
        return {"error": f"generate should return (TokenSpan, new_past_key_values); got {type(result).__name__}."}, None
    span, cache = result
    calls = model.calls[calls_before:]
    produced = calls[-1]["past_out"] if calls else None
    try:
        cache_length = cache.get_seq_length() if hasattr(cache, "get_seq_length") else None
    except Exception:
        cache_length = None
    return {"error": None, "span": span_facts(span, tokenizer), "expected": model.next_token(int(input_ids[0, -1])),
            "model_called": bool(calls), "cache_is_models": cache is not None and cache is produced,
            "cache_length": cache_length, "past_reached_model": None}, cache


def generate_facts(generate, device):
    tokenizer = gpt_tokenizer()
    cases = []
    for name, shift in GENERATE_SHIFTS.items():
        model = scripted_gpt(generate_rule(shift), device)
        model.next_token = generate_rule(shift)
        for text in GENERATE_INPUTS:
            ids = tokenizer.encode(text, return_tensors="pt").to(device)
            facts, _ = generate_case(generate, model, ids, tokenizer, attention_mask=torch.ones_like(ids),
                                     position_ids=torch.arange(ids.shape[1], device=device).unsqueeze(0),
                                     past_key_values=None)
            cases.append({"model": name, "text": text, **facts})

    # The cache: generate once, then generate the next token from the cache, as the spec describes:
    # only the new token, its position, and a mask over everything so far.
    model = scripted_gpt(generate_rule(0), device)
    model.next_token = generate_rule(0)
    ids = tokenizer.encode(GENERATE_INPUTS[0], return_tensors="pt").to(device)
    first, cache = generate_case(generate, model, ids, tokenizer, attention_mask=torch.ones_like(ids),
                                 position_ids=torch.arange(ids.shape[1], device=device).unsqueeze(0),
                                 past_key_values=None)
    second = {"error": "Skipped: the first generate call failed."}
    if not first.get("error") and first["span"].get("ids"):
        new = torch.tensor([[first["span"]["ids"][-1]]], device=device)
        calls_before = len(model.calls)
        second, _ = generate_case(generate, model, new, tokenizer,
                                  attention_mask=torch.ones(1, ids.shape[1] + 1, dtype=torch.long, device=device),
                                  position_ids=torch.tensor([[ids.shape[1]]], device=device), past_key_values=cache)
        if not second.get("error"):
            second["past_reached_model"] = cache is not None and any(
                c["past_in"] is cache for c in model.calls[calls_before:])
    return {"cases": cases, "cache": {"first": first, "second": second, "prompt_length": ids.shape[1]}}


def retrieve_facts(retrieve, device):
    tokenizer, vocab = gpt_tokenizer(), build_vocab()
    kvs = RETRIEVE_KV[RETRIEVE_PERSON]
    cases = []
    for mode in ("sum", "reverse"):
        memnet = scripted_memnet(mode, vocab, device)
        for query in RETRIEVE_QUERIES:
            calls_before = len(memnet.calls)
            result, error = call_student(retrieve, "retrieve", memnet, RETRIEVE_PERSON, dict(RETRIEVE_KV), query,
                                         vocab, tokenizer)
            calls = memnet.calls[calls_before:]
            call = calls[-1] if calls else None
            expected = row_value(call["rows"][call["target"]], kvs, vocab) if call and call["n_rows"] else None
            query_words = [vocab[w] for w in tokenize(query) if w in vocab]
            cases.append({"mode": mode, "query": query, "error": error,
                          "span": None if error or result is None else span_facts(result, tokenizer),
                          "returned_none": not error and result is None, "memnet_called": bool(calls),
                          "expected": expected, "x_len": call and call["x_len"], "x_active": call and call["x_active"],
                          "n_rows": call and call["n_rows"], "last_word": query_words[-1] if query_words else None})
    memnet = scripted_memnet("sum", vocab, device)
    result, error = call_student(retrieve, "retrieve", memnet, UNKNOWN_PERSON, dict(RETRIEVE_KV), RETRIEVE_QUERIES[0],
                                 vocab, tokenizer)
    unknown = {"error": error, "returned_none": not error and result is None, "type": type(result).__name__}
    return {"cases": cases, "unknown": unknown, "vocab_size": len(vocab), "n_keys": len(kvs)}


def can_split(ids, pieces):
    """Whether ids is a concatenation of some of pieces (each may be used any number of times)."""
    pieces = {tuple(p) for p in pieces if p}
    reachable = [True] + [False] * len(ids)
    for i in range(len(ids)):
        if reachable[i]:
            for p in pieces:
                if tuple(ids[i:i + len(p)]) == p:
                    reachable[i + len(p)] = True
    return reachable[len(ids)]


class Spies:
    """Wraps the notebook's trigger_retrieval, generate and retrieve while generate_biography runs,
    recording what each returned."""

    def __init__(self, namespace):
        self.namespace = namespace

    def __enter__(self):
        self.log = {"trigger_retrieval": [], "generate": [], "retrieve": []}
        self.originals = {}
        for name in self.log:
            fn = self.namespace.get(name)
            if callable(fn):
                self.originals[name] = fn
                self.namespace[name] = self._wrap(name, fn)
        return self

    def _wrap(self, name, fn):
        @functools.wraps(fn)
        def spy(*args, **kwargs):
            result = fn(*args, **kwargs)
            span = result[0] if name == "generate" and isinstance(result, tuple) and result else result
            self.log[name].append(ids_of(span) if hasattr(span, "tokens") else None)
            return result
        return spy

    def __exit__(self, *exc):
        self.namespace.update(self.originals)


def bio_run(generate_biography, person, mode, vocab, device):
    tokenizer = gpt_tokenizer()
    gpt = scripted_gpt(bio_rule(), device)
    router = scripted_router(mode, device)
    memnet = scripted_memnet("router", vocab, device, router=router)
    person_to_kv = {name: list(kvs) for name, kvs in PERSON_TO_KV.items()}
    with Spies(getattr(generate_biography, "__globals__", {})) as spies:
        result, error = call_student(generate_biography, "generate_biography", person, list(PROMPT_BANK), person_to_kv,
                                     gpt, tokenizer, router, spy_tokenizer(), memnet, vocab)
    if error:
        return {"error": f"generate_biography({person!r}, ...): {error}"}
    if type(result).__name__ != "TokenDoc" or not hasattr(result, "spans"):
        return {"error": f"generate_biography should return the TokenDoc document, got {type(result).__name__}."}
    spans = [{"type": type_name(span), "ids": ids_of(span), "text": tokenizer.decode(ids_of(span)),
              "token_texts": [tokenizer.decode([i]) for i in ids_of(span)]} for span in result.spans]
    pieces = {name: [p for p in log if p] for name, log in spies.log.items()}
    for span in spans:
        if span["type"] == "RETRIEVED":
            span["from_function"] = can_split(span["ids"], pieces["retrieve"])
        elif span["type"] == "GENERATED":
            span["from_function"] = can_split(span["ids"], pieces["generate"])
    return {"error": None, "spans": spans, "calls": {name: len(log) for name, log in spies.log.items()}}


def bio_facts(generate_biography, device):
    vocab = build_vocab()
    return {"runs": {mode: {person: bio_run(generate_biography, person, mode, vocab, device) for person in PEOPLE}
                     for mode in ("cues", "never")}}

