def kv_pairs(person_to_kv, name):
    """person_to_kv[name] as (relation, value) pairs, with semicolon-separated values split."""
    pairs = []
    for kv in person_to_kv.get(name, []):
        pairs += [(kv[0], v.strip()) for v in str(kv[1]).split(";") if v.strip()]
    return pairs


def report_on_your_models(generate_biography, person_to_kv, gpt_model, gpt_tokenizer, router_model, router_tokenizer,
                          qkmem_model, vocab, people=None):
    """Runs generate_biography with your real models on a few people and prints, per bio, the facts it
    retrieved and whether each retrieval's relation is the one a cue regex (RELATION_CUES) expects from
    the text before it."""
    people = people or random.Random(REPORT_SEED).sample(sorted(person_to_kv), min(REPORT_PEOPLE, len(person_to_kv)))
    totals = {"bios": 0, "with_fact": 0, "found": 0, "facts": 0, "cued": 0, "agree": 0}
    for name in people:
        doc = generate_biography(name, REPORT_PROMPT_BANK, person_to_kv, gpt_model, gpt_tokenizer, router_model,
                                 router_tokenizer, qkmem_model, vocab)
        pairs = kv_pairs(person_to_kv, name)
        before, retrievals = "", []
        for span in doc.spans:
            text = span.tokenizer.decode(ids_of(span))
            if type_name(span) == "PROMPT" and before:
                before += " "
            if type_name(span) == "RETRIEVED":
                relations = sorted({r for r, v in pairs if contains_value(text, v)})
                retrievals.append((text.strip(), cue_relation(before), relations))
            before += text
        found = sorted({v for r, v in pairs if any(contains_value(t, v) for t, _, _ in retrievals)})
        cued = [(t, cue, rel) for t, cue, rel in retrievals if cue]
        values = {v for _, v in pairs}
        totals["bios"] += 1
        totals["with_fact"] += bool(found)
        totals["found"] += len(found)
        totals["facts"] += len(values)
        totals["cued"] += len(cued)
        totals["agree"] += sum(cue in relations for _, cue, relations in cued)
        print(f"=== {name}\n{doc}\n")
        print(f"  Facts retrieved: {len(found)} of {len(values)}: {found}")
        for text, cue, relations in retrievals:
            verdict = "no cue" if not cue else ("agrees" if cue in relations else "DISAGREES")
            print(f"  retrieved {text!r} ({', '.join(relations) or 'not a fact of this person'}); "
                  f"cue regex expected {cue or '-'}: {verdict}")
        print()
    print(f"Your models: {totals['with_fact']} of {totals['bios']} bios retrieved at least one fact; "
          f"{totals['found']} of {totals['facts']} facts retrieved; retrieved relation matched the cue regex "
          f"{totals['agree']} of {totals['cued']} times. (Not part of the total.)")

