def run_tests(t, tests):
    """Runs each (number, test) on t, prints its score and problem, and returns the points earned."""
    total = 0
    for number, test in tests:
        t.score = None
        problem = None
        try:
            test()
            score = POINTS[number] if t.score is None else t.score
        except Exception as e:  # a failed check, or the check itself crashed on unexpected output
            problem = str(e) if isinstance(e, AssertionError) else f"{type(e).__name__}: {e}"
            score = t.score or 0
        print(f"{number} {test.__doc__}: {score:g}/{POINTS[number]:g}")
        if problem:
            print("  " + problem.replace("\n", "\n  "))
        total += score
    return total


def run_all(trigger_retrieval, generate, retrieve, generate_biography, person_to_kv=None, gpt_model=None,
            gpt_tokenizer=None, router_model=None, router_tokenizer=None, qkmem_model=None, vocab=None, people=None):
    """Run every test, print each result, and return the total score.

    The tests run your four functions on scripted stand-in models, as on Gradescope. If you also pass
    your data and models, your generate_biography then runs on REPORT_PEOPLE people sampled from
    person_to_kv (or on `people`, a list of names). That report is not part of the total."""
    t = TestPartC()
    t.trigger_retrieval, t.generate, t.retrieve, t.generate_biography = \
        trigger_retrieval, generate, retrieve, generate_biography
    t.device = getattr(generate_biography, "__globals__", {}).get("DEVICE", "cpu")
    tests = [
        ("1.1", t.test_trigger_uses_given_tokenizer),
        ("1.2", t.test_trigger_follows_router),
        ("2.1", t.test_generate_returns_one_token_span),
        ("2.2", t.test_generate_token_comes_from_model),
        ("2.3", t.test_generate_uses_kv_cache),
        ("3.1", t.test_retrieve_returns_span),
        ("3.2", t.test_retrieve_follows_memnet),
        ("3.3", t.test_retrieve_encodes_query_and_keys),
        ("4.1", t.test_bio_has_every_prompt),
        ("4.2", t.test_bio_uses_the_three_functions),
        ("4.3", t.test_router_drives_retrieval),
        ("4.4", t.test_fact_coverage),
        ("4.5", t.test_sentences_end),
    ]
    missing = missing_on_gradescope([f for f in (trigger_retrieval, generate, retrieve, generate_biography)
                                     if callable(f)])
    if missing:
        print("These notebook variables won't exist on Gradescope, which runs only imports, functions, "
              "classes, and constants. Use the function's arguments instead:")
        for name, variables in missing.items():
            print(f"  {name} uses {', '.join(sorted(variables))}")
        print()

    print("Part C/D self-tests (scripted test models, as on Gradescope)")
    total = run_tests(t, tests)
    print(f"Total: {total:g}/{sum(POINTS.values()):g}")

    models = (person_to_kv, gpt_model, gpt_tokenizer, router_model, router_tokenizer, qkmem_model, vocab)
    if all(m is not None for m in models):
        print("\nYour generate_biography with your real models (not counted)\n")
        report_on_your_models(generate_biography, *models, people=people)
    return total
